def comp_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def comp_add(out,term,support_ids):
    support=comp_unique(support_ids)
    for row in out:
        if row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def comp_union(items):
    items=comp_unique(items)
    if not items:
        return None
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def comp_and(items):
    if not items:
        return ['no_condition']
    value=items[0]
    i=1
    while i<len(items):
        value=['and_condition',value,items[i]]
        i+=1
    return value

def comp_material(kind,raw):
    base=['confidential_information']
    if kind=='confidential_information_and_copies':
        return ['information_bundle',base,['copies_of',['confidential_information']]]
    if kind=='information_copies_and_derivatives':
        return ['information_bundle',['information_bundle',base,['copies_of',['confidential_information']]],['derivative_materials_of',['confidential_information']]]
    if kind=='confidential_information_only':
        return base
    return ['source_stated_information',raw]

def comp_trigger(kind,raw):
    if kind=='request':
        return ['request_by',['disclosing_party']]
    if kind=='relationship_nonformation_deadline':
        return ['relationship_nonformation_deadline']
    if kind=='project_end':
        return ['project_termination']
    if kind=='agreement_end':
        return ['agreement_termination']
    if kind=='service_end':
        return ['service_termination']
    return ['source_stated_trigger',raw]

def comp_exception(kind,a,b,raw):
    if kind=='no_acquired_exception':
        return ['no_exceptions']
    text=a
    if b:
        text=text+' '+b
    if not text:
        text=raw
    return ['source_scoped_exception_set',text]

def comp_role(role,owner):
    holder=['controlled_entities_of',['receiving_party']] if owner=='controlled_entity' else ['receiving_party']
    if role=='employee':
        return ['employees_of',holder]
    if role=='consultant':
        return ['consultants_of',holder]
    if role=='contractor':
        return ['independent_contractors_of',holder]
    if role=='agent':
        return ['agents_of',holder]
    if role=='professional_adviser':
        return ['professional_advisors_of',holder]
    if role=='representative':
        return ['representatives_of',holder]
    return None

def comp_conditions(need,extent,confidentiality,raw):
    items=[]
    if need=='required':
        items.append(['need_to_know',raw])
    if extent=='required':
        items.append(['extent_necessary',raw])
    if confidentiality in ('required','written_required'):
        items.append(['confidentiality_bound',raw])
    return comp_and(items)

def comp_support(rows):
    out=[]
    for row in rows:
        for uid in row.get('support_ids',[]):
            if uid not in out:
                out.append(uid)
    return out

def apply(inputs,premises):
    source=inputs.get('source_output',{})
    out=[]
    unresolved=[]
    complete=False
    rows=[]
    if isinstance(source,dict):
        complete=bool(source.get('complete',False))
        for row in source.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                rows.append(row)
                comp_add(out,row.get('term'),row.get('support_ids',[]))
        for item in source.get('unresolved',[]):
            if isinstance(item,str) and item not in unresolved:
                unresolved.append(item)
    actions={}
    links=[]
    disclosures={}
    for row in rows:
        term=row.get('term')
        if not isinstance(term,list) or not term:
            continue
        if term[0]=='acq_disposal_action_v3' and len(term)==12:
            actions[term[2]]=row
        elif term[0]=='acq_disposal_link_v3' and len(term)==6:
            links.append(row)
        elif term[0]=='acq_disclosure_v3' and len(term)==11:
            scope=term[1]
            group=disclosures.get(scope,[])
            group.append(row)
            disclosures[scope]=group
        elif term[0]=='acq_retention_v3' and len(term)==7:
            material=['source_stated_information',term[6]]
            condition=['retention_condition',term[6]]
            if term[2]=='retention_permission':
                comp_add(out,['retention_permission',['receiving_party'],material,['after_disposal'],condition],row.get('support_ids',[]))
            elif term[2]=='retention_prohibition':
                comp_add(out,['retention_prohibition',['receiving_party'],material,['after_disposal']],row.get('support_ids',[]))
        elif term[0]=='acq_residual_v3' and len(term)==3 and term[1]=='affiliate_cause_disposal_reference':
            raw=term[2]
            affiliate=['controlled_entities_of',['receiving_party']]
            material=['confidential_information']
            inner=['action_alternative',['return_to',material,['disclosing_party']],['destroy',material]]
            action=['cause_disposal',affiliate,inner,raw]
            trigger=['trigger_conjunction',['request_by',['disclosing_party']],['affiliate_exit']]
            exceptions=['exception_set',['cross_reference_exception',raw]]
            comp_add(out,['disposal_obligation',['receiving_party'],action,trigger,exceptions],row.get('support_ids',[]))
    linked=set()
    for row in links:
        term=row.get('term')
        left=actions.get(term[2])
        right=actions.get(term[3])
        if not isinstance(left,dict) or not isinstance(right,dict):
            continue
        lt=left.get('term')
        rt=right.get('term')
        if lt[6]!=rt[6]:
            continue
        la=['return_to',comp_material(lt[5],lt[11]),['disclosing_party']] if lt[3]=='return' else ['destroy',comp_material(lt[5],lt[11])]
        ra=['return_to',comp_material(rt[5],rt[11]),['disclosing_party']] if rt[3]=='return' else ['destroy',comp_material(rt[5],rt[11])]
        if term[4]=='and':
            action=['action_conjunction',la,ra]
        else:
            action=['action_alternative',la,ra]
        trigger=comp_trigger(lt[6],term[5])
        exceptions=comp_exception(lt[8],lt[9],lt[10],lt[11])
        support=comp_support([left,right,row])
        comp_add(out,['disposal_obligation',['receiving_party'],action,trigger,exceptions],support)
        linked.add(term[2])
        linked.add(term[3])
    for action_id in actions:
        if action_id in linked:
            continue
        row=actions[action_id]
        term=row.get('term')
        material=comp_material(term[5],term[11])
        action=['return_to',material,['disclosing_party']] if term[3]=='return' else ['destroy',material]
        trigger=comp_trigger(term[6],term[11])
        exceptions=comp_exception(term[8],term[9],term[10],term[11])
        comp_add(out,['disposal_obligation',['receiving_party'],action,trigger,exceptions],row.get('support_ids',[]))
    for scope in disclosures:
        group=disclosures[scope]
        recipients=[]
        support=comp_support(group)
        first=group[0].get('term')
        raw=first[10]
        for row in group:
            term=row.get('term')
            recipient=comp_role(term[4],term[5])
            if recipient is not None:
                recipients.append(recipient)
        recipient=comp_union(recipients)
        if recipient is not None:
            condition=comp_conditions(first[6],first[7],first[8],raw)
            permission=['permission',['receiving_party'],['disclose',['confidential_information'],recipient],condition]
            comp_add(out,permission,support)
    return {'statements':out,'complete':complete and len(unresolved)==0,'unresolved':comp_unique(unresolved)}

