def sp_low(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold().strip()

def sp_any(text,parts):
    for part in parts:
        if part in text:
            return True
    return False

def sp_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def sp_add(out,term,support_ids):
    support=sp_unique(support_ids)
    for row in out:
        if isinstance(row,dict) and row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def sp_has(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def sp_text(span):
    value=span.get('text','')
    if not isinstance(value,str):
        value=str(value)
    return value

def sp_support_text(row,by_id):
    parts=[]
    for uid in row.get('support_ids',[]):
        span=by_id.get(uid)
        if isinstance(span,dict):
            parts.append(sp_text(span))
    return ' '.join(parts)

def sp_false_old(row,by_id):
    if not isinstance(row,dict):
        return False
    term=row.get('term')
    if not isinstance(term,list) or not term or term[0]!='disposal_obligation':
        return False
    if not sp_has(term,'action_alternative') or not sp_has(term,'request_by'):
        return False
    text=sp_low(sp_support_text(row,by_id))
    return 'upon request or destroyed within' in text and sp_any(text,['termination of the project','expiration of the project','expiration or other termination of the project'])

def sp_exceptions(spans,start,limit):
    backup=''
    legal=''
    ids=[]
    stop=min(len(spans),start+limit+1)
    i=start+1
    while i<stop:
        raw=sp_text(spans[i])
        text=sp_low(raw)
        if not backup and sp_any(text,['back-up/archival','backup/archival','back-up or archival','backup or archival']):
            backup=raw
            ids.append(spans[i].get('id'))
        if not legal and 'single copy' in text and sp_any(text,['legal department','dispute resolution']):
            legal=raw
            ids.append(spans[i].get('id'))
        i+=1
    if backup and legal:
        return ['backup_archive_and_legal_record',backup,legal,sp_unique(ids)]
    if backup:
        return ['backup_archive',backup,'',sp_unique(ids)]
    if legal:
        return ['legal_dispute_record','',legal,sp_unique(ids)]
    return ['no_acquired_exception','','',[]]

def sp_emit_action(out,scope,action_id,kind,mode,material,trigger,timing,exception,raw,support):
    sp_add(out,['acq_disposal_action_v3',scope,action_id,kind,mode,material,trigger,timing,exception[0],exception[1],exception[2],raw],support+exception[3])

def sp_emit_linked(out,scope,raw,branch_raw,trigger,timing,support):
    exception=['no_acquired_exception','','',[]]
    rid=scope+':return'
    did=scope+':destroy'
    sp_emit_action(out,scope,rid,'return','linked','confidential_information_and_copies',trigger,timing,exception,raw,support)
    sp_emit_action(out,scope,did,'destroy','linked','confidential_information_and_copies',trigger,timing,exception,raw,support)
    sp_add(out,['acq_disposal_link_v3',scope,rid,did,'or',raw+' '+branch_raw],support)

def sp_emit_disclosure(out,scope,raw,support):
    text=sp_low(raw)
    need='required' if sp_any(text,['need to know','need-to-know','bona fide need']) else 'not_stated'
    extent='required' if sp_any(text,['involved in the performance','extent necessary','strictly necessary','disclosure is necessary']) else 'not_stated'
    confidentiality='written_required' if sp_any(text,['written agreement','bound in writing','agreed to be bound in writing']) else 'required' if sp_any(text,['bound by obligations','treat the confidential information','terms no less stringent']) else 'not_stated'
    roles=[]
    if sp_any(text,['employee','staff','personnel']):
        roles.append(['employee','receiving_party'])
    if 'consultant' in text:
        roles.append(['consultant','receiving_party'])
    if 'contractor' in text:
        roles.append(['contractor','receiving_party'])
    if 'agent' in text:
        roles.append(['agent','receiving_party'])
    if sp_any(text,['professional adviser','professional advisor','legal adviser','legal advisor','financial adviser','financial advisor']):
        roles.append(['professional_adviser','receiving_party'])
    if 'representative' in text:
        roles.append(['representative','receiving_party'])
    if sp_any(text,['legal entity that it controls','under common control','companies directly or indirectly owned or controlled']):
        roles.append(['employee','controlled_entity'])
    roles=sp_unique(roles)
    for role in roles:
        sp_add(out,['acq_disclosure_v3',scope,'class_permission','receiving_party',role[0],role[1],need,extent,confidentiality,'source_stated_exception',raw],support)

def apply(inputs,premises):
    spans=[]
    by_id={}
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
            by_id[span.get('id')]=span
    old=inputs.get('source_output',{})
    statements=[]
    unresolved=[]
    complete=False
    if isinstance(old,dict):
        complete=bool(old.get('complete',False))
        for row in old.get('statements',[]):
            if isinstance(row,dict) and not sp_false_old(row,by_id):
                sp_add(statements,row.get('term'),row.get('support_ids',[]))
        for item in old.get('unresolved',[]):
            if isinstance(item,str) and item not in unresolved:
                unresolved.append(item)
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        raw=sp_text(spans[i])
        text=sp_low(raw)
        if 'written agreement with the following persons or entities' in text and 'may disclose' in text:
            stop=min(len(spans),i+6)
            j=i+1
            while j<stop:
                child=sp_text(spans[j])
                ct=sp_low(child)
                if sp_any(ct,['employee','representative','agent','consultant','contractor']) and 'confidential information' in ct:
                    sp_emit_disclosure(statements,'disclosure:'+str(uid)+':'+str(spans[j].get('id')),raw+' '+child,[uid,spans[j].get('id')])
                    break
                j+=1
        if 'except its employees' in text and 'representatives' in text and 'performance of the project' in text:
            support=[uid]
            combined=raw
            stop=min(len(spans),i+4)
            j=i+1
            while j<stop:
                follow=sp_text(spans[j])
                ft=sp_low(follow)
                if 'representatives' in ft and sp_any(ft,['bound in writing','agreed to be bound in writing']):
                    combined=combined+' '+follow
                    support.append(spans[j].get('id'))
                    break
                j+=1
            sp_emit_disclosure(statements,'disclosure:'+str(uid),combined,support)
        if 'shall be returned' in text and 'or destroyed:' in text:
            stop=min(len(spans),i+4)
            j=i+1
            while j<stop:
                branch=sp_text(spans[j])
                bt=sp_low(branch)
                bid=spans[j].get('id')
                if sp_any(bt,['business relationship is not entered','fail to enter into a business relationship']):
                    sp_emit_linked(statements,'disposal:'+str(uid)+':'+str(bid),raw,branch,'relationship_nonformation_deadline','three_months_after_both_parties_signed',[uid,bid])
                elif sp_any(bt,['promptly upon request','upon request']) and sp_any(bt,['at any time','promptly']):
                    sp_emit_linked(statements,'disposal:'+str(uid)+':'+str(bid),raw,branch,'request','prompt',[uid,bid])
                j+=1
        if 'returned to the disclosing party upon request or destroyed within' in text and sp_any(text,['termination of the project','expiration of the project','expiration or other termination of the project']):
            exception=sp_exceptions(spans,i,4)
            support=[uid]
            sp_emit_action(statements,'disposal:'+str(uid)+':request','disposal:'+str(uid)+':return','return','atomic','confidential_information_and_copies','request','no_explicit_return_deadline',exception,raw,support)
            sp_emit_action(statements,'disposal:'+str(uid)+':project','disposal:'+str(uid)+':destroy','destroy','atomic','confidential_information_and_copies','project_end','ten_business_days',exception,raw,support)
        if sp_any(text,['upon written demand by the disclosing party or upon termination of this confidentiality agreement','upon written demand by the disclosing party or upon termination of the agreement']):
            stop=min(len(spans),i+4)
            j=i+1
            while j<stop:
                action_raw=sp_text(spans[j])
                at=sp_low(action_raw)
                if 'return the confidential information and all copies' in at:
                    aid=spans[j].get('id')
                    exception=sp_exceptions(spans,j,6)
                    support=[uid,aid]
                    sp_emit_action(statements,'disposal:'+str(uid)+':demand','disposal:'+str(uid)+':demand:return','return','atomic','information_copies_and_derivatives','request','ten_business_days_after_receipt_of_demand',exception,action_raw,support)
                    sp_emit_action(statements,'disposal:'+str(uid)+':termination','disposal:'+str(uid)+':termination:return','return','atomic','information_copies_and_derivatives','agreement_end','no_explicit_termination_deadline',exception,action_raw,support)
                    break
                j+=1
        if 'shall cause such corporate affiliate to return or destroy all confidential information' in text and 'in accordance with section' in text:
            sp_add(statements,['acq_residual_v3','affiliate_cause_disposal_reference',raw],[uid])
            message='affiliate cause-disposal reference retained for source-conditioned composition at unit '+str(uid)
            if message not in unresolved:
                unresolved.append(message)
            complete=False
        if sp_any(text,['back-up/archival storage','backup/archival storage']):
            sp_add(statements,['acq_retention_v3','retention:'+str(uid),'retention_permission','backup_or_archive','backup_archival_copies','continuing_confidentiality_and_source_access_limits',raw],[uid])
        if 'single copy of all confidential information may be retained' in text and sp_any(text,['legal department','dispute resolution']):
            sp_add(statements,['acq_retention_v3','retention:'+str(uid),'retention_permission','dispute_resolution_record','single_copy_all_confidential_information','legal_department_only_and_continuing_confidentiality',raw],[uid])
        i+=1
    return {'statements':statements,'complete':complete and len(unresolved)==0,'unresolved':sp_unique(unresolved)}
